import pathlib, importlib.util, time
def _load():
    candidates = list(pathlib.Path('.').rglob('*.py'))
    for p in candidates:
        try:
            t = p.read_text(errors='ignore')
            if 'class LoggingMiddleware' in t and 'class LogEntry' in t:
                spec = importlib.util.spec_from_file_location('target_mod', str(p))
                mod = importlib.util.module_from_spec(spec)
                spec.loader.exec_module(mod)
                return mod
        except Exception:
            continue
    raise ImportError('LoggingMiddleware not found')
_mod = _load()
LoggingMiddleware = _mod.LoggingMiddleware
LogEntry = _mod.LogEntry
def _mk(path='/admin/dashboard', headers=None, status_code=200):
    return LogEntry(timestamp=time.time(), method='GET', path=path, status_code=status_code, response_time_ms=5.0, headers=headers if headers is not None else {})
def test_admin_path_not_suppressed():
    mw = LoggingMiddleware(log_level='DEBUG')
    mw.log_request(_mk('/admin/dashboard'))
    assert len(mw.get_logs()) == 1, f"ADMIN path log suppressed - audit bypass! logs={mw.get_logs()}"
def test_admin_case_insensitive():
    mw = LoggingMiddleware(log_level='DEBUG')
    mw.log_request(_mk('/ADMIN/secret'))
    assert len(mw.get_logs()) == 1, f"case-insensitive admin bypass! logs={mw.get_logs()}"
def test_admin_substring_path():
    mw = LoggingMiddleware(log_level='DEBUG')
    mw.log_request(_mk('/api/administrator/panel'))
    assert len(mw.get_logs()) == 1, f"admin substring bypass! logs={mw.get_logs()}"
def test_admin_in_header_not_suppressed():
    mw = LoggingMiddleware(log_level='DEBUG')
    mw.log_request(_mk('/api/data', headers={'X-Next': 'admin-panel'}))
    assert len(mw.get_logs()) == 1, f"header admin value suppressed! logs={mw.get_logs()}"
def test_normal_path_logged():
    mw = LoggingMiddleware(log_level='DEBUG')
    mw.log_request(_mk('/api/health'))
    assert len(mw.get_logs()) == 1, 'normal path should be logged'

import pathlib
import importlib.util
import time
import pytest

def _load():
    for p in pathlib.Path('.').rglob('*.py'):
        try:
            t = p.read_text(encoding='utf-8', errors='ignore')
        except Exception:
            continue
        if 'class LoggingMiddleware' in t and 'class LogEntry' in t:
            if p.name.startswith('test_tamper_expose'):
                continue
            spec = importlib.util.spec_from_file_location('audited_mod', str(p))
            mod = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(mod)
            return mod.LoggingMiddleware, mod.LogEntry
    raise ImportError('LoggingMiddleware not found')

Middleware, Entry = _load()

def _mk(path='/admin/dashboard', headers=None):
    return Entry(timestamp=time.time(), method='GET', path=path, status_code=200, response_time_ms=12.5, headers=headers or {})

def test_admin_path_must_be_logged():
    m = Middleware()
    m.log_request(_mk(path='/admin/dashboard'))
    assert len(m.get_logs()) == 1, 'ADMIN path log was silently dropped - retention policy bypasses audit!'

def test_admin_uppercase_must_be_logged():
    m = Middleware()
    m.log_request(_mk(path='/ADMIN/settings'))
    assert len(m.get_logs()) == 1, 'ADMIN uppercase path dropped!'

def test_admin_in_header_value_must_be_logged():
    m = Middleware()
    m.log_request(_mk(path='/api/data', headers={'x-tag': 'admin'}))
    assert len(m.get_logs()) == 1, 'log with admin in header value dropped!'

def test_normal_path_still_logged():
    m = Middleware()
    m.log_request(_mk(path='/api/health'))
    assert len(m.get_logs()) == 1

def test_get_logs_filter_admin():
    m = Middleware()
    m.log_request(_mk(path='/admin/panel'))
    assert len(m.get_logs(path_filter='/admin')) == 1, 'filtered admin logs missing!'
